export function previewImage(file:any) {
  return URL.createObjectURL(file)
}

export const Languages = [{slug: 'en', title: 'English'}, {slug: 'fa', title: 'فارسی'}]
<script setup lang="ts">
import {ref, onMounted} from "vue";
import {previewImage} from "../../../../utilities";
const config = useRuntimeConfig()
const props = defineProps<{
  height: string,
  autoplayDelay:number,
  slidesData: {
    description: string,
    image1: any,
    image2: any,
    image1Size: "tall" | "wide",
    image2Size: "tall" | "wide",
    imagesPosition: "from_left" | "from_right",
    background: string,
  }[]
}>()
//@ts-ignore
import gsap from "gsap";
import Spacer from "./common/Spacer.vue";
import Flex from "./common/Flex.vue";


const currentIndex = ref(0);
const animating = ref(false);

const slidesRefs = ref<HTMLElement[]>([]);
const slideContainers = ref<HTMLElement[]>([]);

const wrapIndex = (i: number) => {
  const len = props.slidesData.length;
  return (i + len) % len;
};
let autoplayTimer: ReturnType<typeof setInterval> | null = null;
const gotoSlide = (index : number, direction : number) => {
  if (animating.value || index === currentIndex.value) return;
  animating.value = true;
  const nextIndex = wrapIndex(index);

  const currentSlide = slideContainers.value[currentIndex.value];
  const nextSlide = slideContainers.value[nextIndex];

  if (!currentSlide || !nextSlide) {
    animating.value = false;
    return;
  }

  gsap.set(nextSlide, {autoAlpha: 1});

  const tl = gsap.timeline({
    defaults: {duration: 1, ease: "power2.inOut"},
    onComplete: () => {
      animating.value = false;
      currentIndex.value = nextIndex;
    }
  });

  if (!props.slidesData[nextIndex]?.imagesPosition) {
    animating.value = false;
    return;
  }
  const pos = props.slidesData[nextIndex]!.imagesPosition;

  const image1 = nextSlide.querySelector(".image1");
  const image2 = nextSlide.querySelector(".image2");
  const text = nextSlide.querySelector(".slide-text");

  // initial positions
  if (pos === "from_left") {
    if (image1) {
      gsap.set([image1], {x: props.slidesData[index]?.image1Size === 'tall' ? 200 : -200, autoAlpha: 0});
      if (text) gsap.set([text], {y: -200, autoAlpha: 0});
      if (image2) gsap.set([image2], {x: props.slidesData[index]?.image2Size !== 'tall' ? 200 : -200, autoAlpha: 0});
    }
  } else {
    if (image2) {
      gsap.set([image2], {x: props.slidesData[index]?.image2Size === 'tall' ? 200 : -200, autoAlpha: 0});
      if (text) gsap.set([text], {y: -200, autoAlpha: 0});
      if (image1) gsap.set([image1], {x: props.slidesData[index]?.image1Size !== 'tall' ? 200 : -200, autoAlpha: 0});
    }
  }

  const dir = direction > 0 ? "-100%" : "100%";
  gsap.set(nextSlide, {x: direction > 0 ? "100%" : "-100%", autoAlpha: 1});

  tl.to(currentSlide, {
    x: dir,
    autoAlpha: 0,
    duration: 0.8,
    ease: "power2.inOut"
  }, 0)
    .to(nextSlide, {
      x: "0%",
      duration: 0.8,
      ease: "power2.inOut"
    }, 0);
  const changeSlideDuration = 0.7
  if (pos === "from_left") {
    if (text) tl.to(text, {y: 0, autoAlpha: 1}, 0.5 + changeSlideDuration)
    if (image1) tl.to(image1, {x: 0, autoAlpha: 1}, 0.1 + changeSlideDuration)
    if (image2) tl.to(image2, {x: 0, autoAlpha: 1}, 0.2 + changeSlideDuration);
  } else {
    if (text) tl.to(text, {y: 0, autoAlpha: 1}, 0.5 + changeSlideDuration)
    if (image2) tl.to(image2, {x: 0, autoAlpha: 1}, 0.1 + changeSlideDuration)
    if (image1) tl.to(image1, {x: 0, autoAlpha: 1}, 0.2 + changeSlideDuration);
  }


};


onMounted(() => {
  // hide scrollbar

  slideContainers.value = slidesRefs.value.filter((el): el is HTMLElement => el != null);

  slidesRefs.value.forEach((el, i) => {
    gsap.set(el, {autoAlpha: i === 0 ? 1 : 0});
  });
  startAutoplay();

});

function beforeSlide() {
  stopAutoplayTemp();
  if (currentIndex.value === (props.slidesData.length - 1))
    gotoSlide(currentIndex.value - 1, 1)
  else
    gotoSlide(currentIndex.value + 1, 1)
}

function nextSlide() {
  stopAutoplayTemp();
  if (currentIndex.value === 0)
    gotoSlide(currentIndex.value + 1, -1)
  else
    gotoSlide(currentIndex.value - 1, -1)
}

const autoIndex = ref(0)

function startAutoplay() {
  stopAutoplay(); // از قبل اگر تایمر فعاله، پاک بشه
  autoplayTimer = setInterval(() => {
    autoIndex.value = autoIndex.value + 1;
      gotoSlide(autoIndex.value, -1)
  }, props.autoplayDelay);
}

function stopAutoplay() {
  if (autoplayTimer) {
    clearInterval(autoplayTimer);
    autoplayTimer = null;
  }
}

function stopAutoplayTemp() {
  stopAutoplay();
  setTimeout(() => {
    startAutoplay();
  }, props.autoplayDelay);
}

</script>

<template>
  <div class="fullpage-slider" :style="{height:height}">
    <i @click="nextSlide()" class="pi pi-chevron-right"
       style="font-size: 2rem ;
       position: absolute;
       z-index: 99 ;
       right:0  ;
        color: white;
        top: 50%;
  transform: translate(-50%, -50%);
  cursor: pointer;
}"></i>
    <i @click="beforeSlide()" class="pi pi-chevron-left"
       style="font-size: 2rem ;
       position: absolute;
       z-index: 99 ;
       left:25px  ;
        color: white;
        top: 50%;
  transform: translate(-50%, -50%);
  cursor: pointer;
}"></i>
    <div
      v-for="(slide, index) in slidesData"
      :key="index"
      ref="slidesRefs"
      class="slide"
      :style="{ background: slide.background }"
    >
      <div
        :key="index+'slide-content'"
        class="slide-content"
        :class="slide.imagesPosition === 'from_left' ? 'left-layout' : 'right-layout'"
      >
        <div :class="['image1',slide.image1Size+'Box']">
          <img
            v-if="slide.image1"
            :src="typeof slide.image1==='object' ? previewImage(slide.image1) : config.public.baseUrl+'/'+slide.image1"
            :class="['image1', slide.image1Size]"
            alt=""
          />
        </div>
        <div :class="['image2',slide.image2Size+'Box']" style="display:flex;flex-direction: column">
          <flex fd="row">
            <div class="slide-text" v-html="slide.description">

            </div>
          </flex>

          <Spacer/>
          <img
            v-if="slide.image2"
            :src="typeof slide.image2==='object' ? previewImage(slide.image2) : config.public.baseUrl+'/'+slide.image2"
            :class="['image2', slide.image2Size]"
            alt=""
          />
        </div>


      </div>
    </div>
  </div>
</template>

<style scoped>
.fullpage-slider {
  position: relative;
  width: 100%;
  overflow: hidden
}

.slide {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  display: flex;
}

.slide-content {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  gap: 2rem;
  padding: 20px 5%;
  box-sizing: border-box;
}

.slide-text {
  width: 100%;
  max-width: 100%;
  color: #fff;
}

.left-layout {
  flex-direction: row;
}

.right-layout {
  flex-direction: row-reverse;
}

.image1.tall {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image1.wide {
  width: 100%;
  height: 75%;
  object-fit: cover;
}

.image2.tall {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image2.wide {
  width: 100%;
  height: 75%;
  object-fit: cover;
}


.image1.tallBox {
  width: 30%;
  height: 100%;
}

.image1.wideBox {
  width: 60%;
  height: 100%;
}

.image2.tallBox {
  width: 30%;
  height: 100%;
}

.image2.wideBox {
  width: 60%;
  height: 100%;
}

.image1, .image2 {
  border-radius: 8px;
}

</style>
